function outputRollingReleaseAgentError(
  client: Client,
  subcmd: 'start' | 'abort' | 'approve' | 'complete',
  reason: 'missing_flags' | 'invalid_flag' | 'api_error',
  message: string
) {
  const { listCommand, subcommandCommand } =
    buildDeploymentSuggestionCommands(client, subcmd);

  outputAgentError(
    client,
    {
      status: 'error',
      reason,
      message,
      next: [{ command: listCommand }, { command: subcommandCommand }],
    },
    1
  );
}

